using System.Text.RegularExpressions;
using LibreKO.Editors.Contracts;
namespace LibreKO.Editors.Core;
public static class CompatibilityRules {
 public static int? VariantId(int definitionId,int extensionId){if(definitionId<0||definitionId%1000!=0||extensionId<0)return null;var id=(long)definitionId+extensionId%1000;return id<=int.MaxValue?(int)id:null;}
 public static bool SupportsInventory(int bytes)=>bytes is 0 or 768 or 864 or 1632 or 2016;
 public static IReadOnlyList<CompatibilityIssue> Compare(CompatibilityItem database,CompatibilityItem? client){
  var key=new RecordKey(RecordKind.Item,database.Id);var target=$"{database.Id} · {database.Name}";
  if(client==null)return [new("catalog.missing",CompatibilitySeverity.Warning,"Items",target,"Database item has no matching client definition. Its image, grade and effects cannot be verified.",key)];
  var differences=new List<string>();
  void Check(string name,object a,object b){if(!Equals(a,b))differences.Add($"{name}: database {a}, client {b}");}
  Check("Name",database.Name.Trim(),client.Name.Trim());Check("Kind",database.Kind,client.Kind);Check("Slot",database.Slot,client.Slot);Check("Extension",database.Extension,client.Extension);Check("Damage",database.Damage,client.Damage);Check("Defense",database.Defense,client.Defense);Check("Duration",database.Duration,client.Duration);
  return differences.Count==0?[]:[new("catalog.different",CompatibilitySeverity.Warning,"Items",target,string.Join("; ",differences)+". Database saves do not synchronize client catalogs.",key)];
 }
 public static IReadOnlyList<CompatibilityIssue> CompareColumns(IReadOnlyList<CompatibilityColumn> expected,IReadOnlyList<CompatibilityColumn> actual){
  var issues=new List<CompatibilityIssue>();
  void Issue(string code,string target,string message)=>issues.Add(new(code,CompatibilitySeverity.Blocking,"Schema",target,message));
  foreach(var column in expected){
   var found=actual.FirstOrDefault(x=>x.Table==column.Table&&x.Name.Equals(column.Name,StringComparison.OrdinalIgnoreCase));var target=column.Table+"."+column.Name;
   if(found==null){Issue("schema.column",target,"Required mapped column is missing.");continue;}
   if(!CompatibleType(column.StoreType,found.StoreType))Issue("schema.type",target,$"Expected {column.StoreType}; found {found.StoreType}. A matching database adapter is required.");
   if(column.Nullable!=found.Nullable)Issue("schema.nullability",target,"Column nullability differs from the editor's mapped contract.");
   if(!column.Generated&&found.Generated)Issue("schema.generated",target,"A mapped editable column is generated by this database.");
  }
  foreach(var table in expected.Select(x=>x.Table).Distinct()){
   var wanted=expected.Where(x=>x.Table==table&&x.PrimaryKey).Select(x=>x.Name).Order().ToArray();var found=actual.Where(x=>x.Table==table&&x.PrimaryKey).Select(x=>x.Name).Order().ToArray();
   if(!wanted.SequenceEqual(found,StringComparer.OrdinalIgnoreCase))Issue("schema.key",table,"Primary key differs; row identity cannot be safely interpreted.");
  }
  foreach(var extra in actual.Where(x=>!expected.Any(e=>e.Table==x.Table&&e.Name.Equals(x.Name,StringComparison.OrdinalIgnoreCase)))){if(!extra.Nullable&&!extra.HasDefault&&!extra.Generated)Issue("schema.required-extra",extra.Table+"."+extra.Name,"Unknown required column has no default. Writes require a matching adapter.");}
  return issues;
 }
 static bool CompatibleType(string expected,string actual){
  static string Normal(string value)=>Regex.Replace(value.ToLowerInvariant().Replace("integer","int"),@"\s+"," ").Trim();
  var e=Normal(expected);var a=Normal(actual);if(e==a)return true;
  var er=Regex.Match(e,@"^(var)?char\((\d+)\)$");var ar=Regex.Match(a,@"^(var)?char\((\d+)\)$");
  if(er.Success&&ar.Success&&er.Groups[1].Value==ar.Groups[1].Value)return int.Parse(ar.Groups[2].Value)>=int.Parse(er.Groups[2].Value);
  // Integer display widths do not change storage size or signedness.
  return Regex.IsMatch(e,@"^(tinyint|smallint|mediumint|int|bigint)(\(\d+\))?( unsigned)?$")&&Regex.Replace(e,@"\(\d+\)","")==Regex.Replace(a,@"\(\d+\)","");
 }
}
public sealed class CompatibilityReportBuilder(int sampleLimit=500){
 readonly Dictionary<string,int> counts=new();readonly List<CompatibilityIssue> examples=new();
 public IReadOnlyDictionary<string,int> Counts=>counts;public IReadOnlyList<CompatibilityIssue> Examples=>examples;public int Total{get;private set;}public int Blocking{get;private set;}public int Warnings{get;private set;}
 public void Add(CompatibilityIssue issue){Total++;if(issue.Severity==CompatibilitySeverity.Blocking)Blocking++;if(issue.Severity==CompatibilitySeverity.Warning)Warnings++;counts[issue.Code]=counts.GetValueOrDefault(issue.Code)+1;if(examples.Count<sampleLimit&&counts[issue.Code]<=Math.Min(50,sampleLimit))examples.Add(issue);}
 public void AddRange(IEnumerable<CompatibilityIssue> issues){foreach(var issue in issues)Add(issue);}
}
